def get_repo_utils_tests() -> list[str]:
    """
    Return the list of repo utility test files (the tests under `tests/repo_utils`).

    These tests are excluded from the model-driven test selection in `infer_tests_to_run`, so they need to be routed
    explicitly (see `should_run_repo_utils_tests` and `create_test_list_from_filter`).
    """
    repo_utils_dir = PATH_TO_TESTS / "repo_utils"
    if not repo_utils_dir.is_dir():
        return []

    tests = [
        str(path.relative_to(PATH_TO_REPO)).replace(os.path.sep, "/")
        for path in repo_utils_dir.glob("test_*.py")
        if path.is_file()
    ]
    return sorted(tests)


def should_run_repo_utils_tests(changed_files: list) -> bool:
    """
    Return whether the repo utility tests should run given a list of changed files.

    The modeling-structure linter lives under `utils/mlinter/`, and its tests live under `tests/repo_utils`, so any
    change to that package must trigger the repo utils tests.
    """
    return any(str(changed_file).replace(os.path.sep, "/").startswith("utils/mlinter/") for changed_file in changed_files)


